package com.example.worldborderevent;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.blaze3d.vertex.VertexConsumer;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.RenderType;import net.minecraft.client.renderer.MultiBufferSource;import net.minecraft.world.level.Level;import net.minecraftforge.client.event.RenderLevelStageEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;import org.joml.Matrix4f;
@Mod.EventBusSubscriber(modid=WorldBorderEventMod.MODID,value=net.minecraftforge.api.distmarker.Dist.CLIENT)
public final class ClientBorderRenderer{private ClientBorderRenderer(){}
@SubscribeEvent public static void render(RenderLevelStageEvent e){if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS)return;Minecraft mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;Level l=mc.level;boolean n=l.dimension()==Level.NETHER;if(!n&&l.dimension()!=Level.OVERWORLD)return;double r=ClientBorderState.getRadius(n),cx=e.getCamera().getPosition().x,cz=e.getCamera().getPosition().z;PoseStack p=e.getPoseStack();p.pushPose();p.translate(-cx,-e.getCamera().getPosition().y,-cz);Matrix4f m=p.last().pose();MultiBufferSource.BufferSource b=mc.renderBuffers().bufferSource();VertexConsumer v=b.getBuffer(RenderType.lines());for(double[] corner:new double[][]{{-r,-r},{-r,r},{r,-r},{r,r}}){line(v,m,corner[0],-64,corner[1],corner[0],320,corner[1],210);}h(v,m,r,-64,210);h(v,m,r,320,210);for(double y=-64;y<=320;y+=16)h(v,m,r,y,80);
if(Math.min(Math.abs(Math.abs(cx)-r),Math.abs(Math.abs(cz)-r))<=128){for(double x=Math.max(-r,cx-96);x<=Math.min(r,cx+96);x+=16){line(v,m,x,-64,-r,x,320,-r,120);line(v,m,x,-64,r,x,320,r,120);}for(double z=Math.max(-r,cz-96);z<=Math.min(r,cz+96);z+=16){line(v,m,-r,-64,z,-r,320,z,120);line(v,m,r,-64,z,r,320,z,120);}}
b.endBatch(RenderType.lines());p.popPose();}
private static void h(VertexConsumer v,Matrix4f m,double r,double y,int a){line(v,m,-r,y,-r,r,y,-r,a);line(v,m,r,y,-r,r,y,r,a);line(v,m,r,y,r,-r,y,r,a);line(v,m,-r,y,r,-r,y,-r,a);}
private static void line(VertexConsumer v,Matrix4f m,double x,double y,double z,double X,double Y,double Z,int a){v.vertex(m,(float)x,(float)y,(float)z).color(35,220,255,a).normal(0,1,0).endVertex();v.vertex(m,(float)X,(float)Y,(float)Z).color(35,220,255,a).normal(0,1,0).endVertex();}}